:root {
  color-scheme: light;
  --canvas: var(--rhoe-canvas, #eef1ed);
  --surface: var(--rhoe-surface, #fcfdfb);
  --surface-muted: var(--rhoe-surface-muted, #e2e6e1);
  --text: var(--rhoe-text, #191b19);
  --text-secondary: var(--rhoe-text-secondary, #59605b);
  --border: var(--rhoe-border, #d9ddd9);
  --primary: var(--rhoe-primary, #252725);
  --primary-hover: var(--rhoe-primary-hover, #343734);
  --primary-foreground: var(--rhoe-primary-foreground, #f8faf8);
  --success: var(--rhoe-success, #18794e);
  --success-foreground: var(--rhoe-success-foreground, #ffffff);
  --success-surface: var(--rhoe-success-surface, #e7f6ec);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #17653f);
  --warning: var(--rhoe-warning, #946200);
  --warning-foreground: var(--rhoe-warning-foreground, #ffffff);
  --warning-surface: var(--rhoe-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #6b4600);
  --danger: var(--rhoe-danger, #b42318);
  --danger-foreground: var(--rhoe-danger-foreground, #ffffff);
  --danger-surface: var(--rhoe-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #8f1d14);
  --focus: var(--rhoe-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --duration-considered: 480ms;
  --duration-reveal: 600ms;
  --duration-expand: 720ms;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --input-expanded-duration: var(--duration-considered);
  --input-expanded-ease: var(--ease-enter);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--rhoe-canvas, #121412);
    --surface: var(--rhoe-surface, #1a1d1a);
    --surface-muted: var(--rhoe-surface-muted, #232623);
    --text: var(--rhoe-text, #f1f3f0);
    --text-secondary: var(--rhoe-text-secondary, #afb5b0);
    --border: var(--rhoe-border, #373b37);
    --primary: var(--rhoe-primary, #ecefeb);
    --primary-hover: var(--rhoe-primary-hover, #ffffff);
    --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
    --success: var(--rhoe-success, #62c98f);
    --success-foreground: var(--rhoe-success-foreground, #092416);
    --success-surface: var(--rhoe-success-surface, #173526);
    --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
    --warning: var(--rhoe-warning, #e9ad45);
    --warning-foreground: var(--rhoe-warning-foreground, #291900);
    --warning-surface: var(--rhoe-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
    --danger: var(--rhoe-danger, #ff716b);
    --danger-foreground: var(--rhoe-danger-foreground, #260503);
    --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
    --focus: var(--rhoe-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--rhoe-canvas, #121412);
  --surface: var(--rhoe-surface, #1a1d1a);
  --surface-muted: var(--rhoe-surface-muted, #232623);
  --text: var(--rhoe-text, #f1f3f0);
  --text-secondary: var(--rhoe-text-secondary, #afb5b0);
  --border: var(--rhoe-border, #373b37);
  --primary: var(--rhoe-primary, #ecefeb);
  --primary-hover: var(--rhoe-primary-hover, #ffffff);
  --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
  --success: var(--rhoe-success, #62c98f);
  --success-foreground: var(--rhoe-success-foreground, #092416);
  --success-surface: var(--rhoe-success-surface, #173526);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
  --warning: var(--rhoe-warning, #e9ad45);
  --warning-foreground: var(--rhoe-warning-foreground, #291900);
  --warning-surface: var(--rhoe-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
  --danger: var(--rhoe-danger, #ff716b);
  --danger-foreground: var(--rhoe-danger-foreground, #260503);
  --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
  --focus: var(--rhoe-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .rhoe-code-source .shiki,
html[data-theme="dark"] .rhoe-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .rhoe-code-source .shiki,
  html:not([data-theme="light"]) .rhoe-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes rhoe-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes rhoe-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes rhoe-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

@keyframes rhoe-calendar-range-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    expand: 0.72,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  forwardRef,
  useId,
  useState,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from "react";
import { Check } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export type CheckboxIndicatorPosition = "leading" | "trailing" | "none";
export type CheckboxListVariant = "default" | "filled-leading" | "filled-trailing" | "selected";

export interface CheckboxProps extends Omit<
  ComponentPropsWithoutRef<"input">,
  "type" | "size" | "checked" | "defaultChecked" | "onChange"
> {
  /** Controlled checked state. */
  checked?: boolean;
  /** Initial uncontrolled checked state. */
  defaultChecked?: boolean;
  /** Receives the next checked state. */
  onCheckedChange?: (checked: boolean) => void;
  /** Visible label associated with the checkbox. */
  label?: ReactNode;
  /** Optional supporting text below the label. */
  description?: ReactNode;
  /** Default compact checkbox or a filled list row. */
  variant?: "default" | "filled";
  /** Places the checkbox before or after its label. */
  indicatorPosition?: CheckboxIndicatorPosition;
}

export interface CheckboxListItem {
  value: string;
  label: ReactNode;
  description?: ReactNode;
  disabled?: boolean;
}

export interface CheckboxListProps {
  /** Options rendered as semantic list items. */
  items: CheckboxListItem[];
  /** Controlled checked values. */
  value?: string[];
  /** Initial uncontrolled checked values. */
  defaultValue?: string[];
  /** Receives the next set of checked values. */
  onValueChange?: (value: string[]) => void;
  /** Accessible name for the list. */
  ariaLabel?: string;
  /** Name shared by all checkbox inputs. */
  name?: string;
  /** Visual treatment for every semantic list row. */
  variant?: CheckboxListVariant;
  /** Additional classes for the list. */
  className?: string;
}

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(function Checkbox({
  checked,
  defaultChecked,
  onCheckedChange,
  label,
  description,
  variant = "default",
  indicatorPosition = "leading",
  className,
  disabled,
  id,
  ...props
}, ref) {
  const reduceMotion = useReducedMotion() ?? false;
  const generatedId = useId();
  const inputId = id ?? `rhoe-checkbox-${generatedId}`;
  const isControlled = checked !== undefined;
  const [internalChecked, setInternalChecked] = useState(defaultChecked ?? false);
  const isChecked = checked ?? internalChecked;

  return (
    <label
      htmlFor={inputId}
      className={[
        "inline-flex cursor-pointer items-start gap-3 select-none",
        variant === "filled" ? "w-full rounded-[18px] bg-[var(--surface-muted)] px-4 py-3.5 transition-colors duration-[var(--duration-fast)] ease-[var(--ease-standard)] hover:bg-[color-mix(in_srgb,var(--surface-muted)_82%,var(--text))]" : "w-fit",
        indicatorPosition === "trailing" && "flex-row-reverse justify-between",
        indicatorPosition === "none" && "gap-0 has-[input:focus-visible]:outline-2 has-[input:focus-visible]:outline-[var(--focus)] has-[input:focus-visible]:outline-offset-3",
        variant === "filled" && indicatorPosition === "none" && isChecked && "border !border-[var(--primary)] !bg-[var(--surface)] hover:!bg-[var(--surface)]",
        disabled && "cursor-not-allowed opacity-[0.48]",
      ].filter(Boolean).join(" ")}
    >
      <span className={indicatorPosition === "none"
        ? "contents"
        : variant === "filled"
          ? "relative inline-flex shrink-0 self-center"
          : "relative mt-0.5 inline-flex shrink-0"}>
        <input
          {...props}
          ref={ref}
          id={inputId}
          type="checkbox"
          className={["peer sr-only", className].filter(Boolean).join(" ")}
          checked={isChecked}
          disabled={disabled}
          onChange={(event) => {
            const nextChecked = event.currentTarget.checked;
            if (!isControlled) setInternalChecked(nextChecked);
            onCheckedChange?.(nextChecked);
          }}
        />
        {indicatorPosition !== "none" ? (
          <span
            className="grid size-5 place-items-center rounded-[6px] border border-[var(--border)] bg-[var(--surface)] text-[var(--primary-foreground)] transition-[background-color,border-color] duration-[var(--duration-fast)] ease-[var(--ease-standard)] peer-checked:border-[var(--primary)] peer-checked:bg-[var(--primary)] peer-focus-visible:outline-2 peer-focus-visible:outline-[var(--focus)] peer-focus-visible:outline-offset-3"
            aria-hidden="true"
          >
            <AnimatePresence initial={false}>
              {isChecked ? (
                <motion.span
                  className="grid place-items-center [&>svg]:size-[14px]"
                  initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.55 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.55 }}
                  transition={reduceMotion ? { duration: 0 } : motionTokens.spring.snappy}
                >
                  <Check />
                </motion.span>
              ) : null}
            </AnimatePresence>
          </span>
        ) : null}
      </span>
      {label ? (
        <span className="min-w-0">
          <span className={`block text-sm leading-6 font-[560] ${variant === "filled" && indicatorPosition === "none" && isChecked ? "text-[var(--primary)]" : "text-[var(--text)]"}`}>{label}</span>
          {description ? <span className={`mt-0.5 block text-[13px] leading-5 ${variant === "filled" && indicatorPosition === "none" && isChecked ? "text-[color-mix(in_srgb,var(--primary)_76%,var(--text-secondary))]" : "text-[var(--text-secondary)]"}`}>{description}</span> : null}
        </span>
      ) : null}
    </label>
  );
});

export function CheckboxList({
  items,
  value,
  defaultValue = [],
  onValueChange,
  ariaLabel = "Checkbox list",
  name,
  variant = "default",
  className,
}: CheckboxListProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const selectedValues = value ?? internalValue;
  const checkboxVariant = variant === "default" ? "default" : "filled";
  const indicatorPosition: CheckboxIndicatorPosition = variant === "filled-trailing"
    ? "trailing"
    : variant === "selected"
      ? "none"
      : "leading";

  const setItemChecked = (itemValue: string, checked: boolean) => {
    const nextValue = checked
      ? [...new Set([...selectedValues, itemValue])]
      : selectedValues.filter((selectedValue) => selectedValue !== itemValue);
    if (value === undefined) setInternalValue(nextValue);
    onValueChange?.(nextValue);
  };

  return (
    <ul className={["m-0 grid list-none gap-3 p-0", className].filter(Boolean).join(" ")} aria-label={ariaLabel}>
      {items.map((item) => (
        <li key={item.value}>
          <Checkbox
            name={name}
            value={item.value}
            checked={selectedValues.includes(item.value)}
            disabled={item.disabled}
            label={item.label}
            description={item.description}
            variant={checkboxVariant}
            indicatorPosition={indicatorPosition}
            onCheckedChange={(checked) => setItemChecked(item.value, checked)}
          />
        </li>
      ))}
    </ul>
  );
}
